from itertools import product

def modeles(variables, formule):
    res = []
    for valeurs in product([False, True], repeat=len(variables)):
        interp = dict(zip(variables, valeurs))
        if formule(interp):
            res.append(valeurs)
    return sorted(res)

def consequence(variables, base, question):
    for valeurs in product([False, True], repeat=len(variables)):
        interp = dict(zip(variables, valeurs))
        if base(interp) and not question(interp):
            return False
    return True

def resolvante(c1, c2, litteral):
    if litteral in c1 and -litteral in c2:
        a, b = c1, c2
    elif -litteral in c1 and litteral in c2:
        a, b = c2, c1
    else:
        return None
    return (a - {litteral}) | (b - {-litteral})

def refuter(clauses):
    connues = [frozenset(c) for c in clauses]
    vues = set(connues)
    while True:
        nouvelles = []
        for i in range(len(connues)):
            for j in range(i + 1, len(connues)):
                for l in connues[i]:
                    if -l in connues[j]:
                        r = resolvante(set(connues[i]), set(connues[j]), l)
                        if r is None:
                            continue
                        if not r:
                            return True
                        f = frozenset(r)
                        if f not in vues:
                            vues.add(f)
                            nouvelles.append(f)
        if not nouvelles:
            return False
        connues = connues + nouvelles

def propager(clauses, aff):
    a = dict(aff)
    change = True
    while change:
        change = False
        for cl in clauses:
            libres, satisfaite = [], False
            for l in cl:
                v, signe = abs(l), l > 0
                if v not in a:
                    libres.append(l)
                elif a[v] == signe:
                    satisfaite = True
            if satisfaite:
                continue
            if not libres:
                return None
            if len(libres) == 1:
                l = libres[0]
                a[abs(l)] = l > 0
                change = True
    return a

def dpll(clauses, n):
    def explorer(aff):
        a = propager(clauses, aff)
        if a is None:
            return None
        choisie = None
        for v in range(1, n + 1):
            if v not in a:
                choisie = v
                break
        if choisie is None:
            return a
        for b in (True, False):
            suivante = dict(a)
            suivante[choisie] = b
            r = explorer(suivante)
            if r is not None:
                return r
        return None
    return explorer({})
